                values: new object[,]
                {
                    { 241, "عزة دياب", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عرف النيل مع رفاقه، وشق الثوب الذي دثّرته به أمه في نسجها الحكايات عن عروس البحر خانقة الصبية، رآها في أحلامه تصاحبه في جزيرة الذهب وتعرّفه على ملوك البحار، عندما ترك جسده للموج الهادئ وأرخاه في حضن موجة تسلمه لأخرى، سبح إلى البر الشرقي وعاد من دون تعب، بالذات في أيام التحاريق قبل الفيضان، جلو صفحة النيل وهدوؤها يُغري بالسباحة كأنه الهدوء الذي يسبق العاصفة، يأتي الفيضان مجتاحًا الشوارع مغرقًا إياها بالطمي والمياه المحمَرّة، تنحسر من الشوارع شيئًا فشيئًا بعدما غسلها النيل وأطعم السردين.\nعمل بالقفاصة، ينهي يوميته قبل المغرب، تأخذه قدماه إلى النيل، يتأمل الصيادين يفردون الشباك بين المراكب، ينزلون طوايل السردين المفضض، ألحقه أبوه بخياط بلدي عند زاوية العقادين، يتركه ويتجه إلى النيل، ألح على أبيه أن يلحقه صيادًا عند أحد معارفه، اشترط عليه أبوه ألا يسمع شكوى منه بعد ذلك، يستقبل النيل قبل طلوع الشمس، يطرح الشِّباك، يلمه بمساعدة زملائه، يهب الوهّاب البلطي والبوري الصايم صيد الليل.", "/images/products/9789776376915.webp", "9789776376915", "روزيتا", 160, 120m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 242, "إيناس بن مبارك", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أفكر ونحن نعبر تلك الأزقة، كلّ البيوت الحجرية التي تعود لأزمنة مُتأصلّة لجدودنا، بعضُ سكانها أُخرج عُنوة وتمّ احتكارها لليهود الذين أتوا بحماية بريطانيا، صُودِرت بعض الشوارع بأكملها، نحن لسنا ضدّ عيشهم هنا، بل ضدّ طردهم لنا ونهب دورنا... خلف كلّ بابٍ خشبيّ قصة، أرواح مُنهكة من الشوق لأيّامٍ ماضية، يعيشون على الماضي، ساعاتهم ضُبِطت على إيقاع الذكريات، ينتظرون أن يعود نبض الحياة لعقاربها لكنّهم لا يجاهدون بشيء لبلوغ ذلك... الإيمان غلّف قلوبهم جاعلًا الذكريات تعيش بكلّ زوايا بيوتهم، وتحت أضواء شوارعهم، حتى بين حجارة طرق شوارعهم، والتي قد تضمّ زهرةً مُتعطّشةً للحياة، استماتت لترى ضوء القدس، قبل أن تدعسها مركبة عسكرية لليهود، يؤمنون أنّ هذا عابر.", "/images/products/9789778200140.webp", "9789778200140", "قلوبنا غلف", 392, 270m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 243, "محمد ابراهيم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحرك عمر بآلية تامّة، يتفحّص وجوه المسلمين، وعيناه تركزان على وجه النبي - صلى الله عليه وسلم - الذي قام بفعل لم يتوقعه أحد. فجأة، ودون أي مقدمات، جذبه النبي جذبة عنيفة.\n\nوفي لحظة نادرة، انهار جسد عمر.\n\nكاد حمزة يتحرك.. بل كاد أبو بكر ينطق.. ولقد حاول علي أن يكسر الصمت، إلا أن كل ذلك لم يحدث. وكأن الأفعال والأقوال ذابت في صمت رهيب.\n\nخيم سكون تام على الجميع، كأن الزمن توقف للحظة لا تتكرر إلا نادرًا في كل جيل، قبل أن يقول النبي صلى الله عليه وسلم: «أما آن يا عمر؟»\n\nتأمل عمر وجه الرسول - صلى الله عليه وسلم - وبهدوء غريب انفرجت شفتاه ليقول: «بلى، آن يا رسول الله.. أشهد أن لا إله إلا الله، وأن محمداً رسول الله.»\n\nانساب الصوت العذب إلى الآذان، ولربما عجزت العقول عن استيعابه، فيما ارتفعت أعناق أهل مكة نحو دار الأرقم بن أبي الأرقم، حيث وُلد فجر جديد، وولدت معه أسطورة عربية، هذه المرة، واسمها عمر.\n\nعمر بن الخطاب.", "/images/products/9789776376717.webp", "9789776376717", "فى بلاط الخليفة", 198, 140m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 244, "محمد إبراهيم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أنا (أوديف) أو (عوديف) إن لم تشعر بريبة ما تجاه نطق الأخير.\nأحب أسمائي جميعها. يدعونني (كورفوس) باللاتينية ـ (كوراكوس) باليونانية، الإسبان يدعونني (ماريا) بينما يسميني الإنجليز (كراو).\nأما عني، فمثلما أخبرتك أم لم أخبرك بعد؟ أفضل لو ناديتني أوديف، أكثر أسمائي أصالة وقربا إلى نفسي وتناغما معي.\nحسنا، لن أطيل عليك الحكي. جئت لأقص عليك حكاية مسلية.\nهل تحب الحكايا؟!\nالناس جميعا تحبها –أعتقد-.\nأعدك بأن تكون حكاياي اليوم مختلفة. ستتسلل عبر أطرافك، وتثير في جسدك رعدة.\nربما ستكون سمعتها من قبل، لكن بطريقة مغايرة.\nأرى ألّا بأس بأن تسمعها اليوم من فم أوديف.\nأراك ترتجف! لا تحب أن تطيل النظر إلى وجهي؟ لكن لا تنكر أن صوتي يجتذبك إلى قصتي. رخيم ويتسلل إلى أعماق روحك القلقة المتعبة.\nيقولون إن التاريخ يكتبه المنتصر، لم لا نسمح بأن يكتبه المهزوم مرة؟\nهل سيراودك الشك تجاه صدق حكايتي؟ لا ألومك. لا أسعى لأن تصدقني. أعلم أنني –ربما- لا أوحي بالثقة. لكن لتعلم بأن أوديف العجوز لا يحب الكذب.\nربما لا أخبرك بالحقيقة كلها، ربما أخفي عنك شطرها. ربما لا أخبرك بالحقيقة أصلا! لكن أعدك بأن أطرح أسئلة طازجة ستدفعك للسؤال وإطالة الفكر.\nحسنا. دعنا من الثرثرة. لم لا نتابع الحكي؟", "/images/products/9789778200676.webp", "9789778200676", "أوديف", 278, 200m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 245, "محمد إبراهيم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور الرواية عن  ثلاثة شباب  قاموابرحلة إلى جنوب سيناء لتلقى دورة\nدورة طبية فى الصيدلة يحاضرفيها واحدمن ألمع الأطباء الشباب فى هذا المجال وختاما\nلتلك الدورة قرورا صعودأحدالجبال لمشاهدة أول ضوء للصباح من أعلى قمته\nإلاأنهم تعرضوا لخديعة ما على يد دليل سيناوى معدوم الضمير،الذى عاد وتركهم\nعرضة للهلاك", "/images/products/9789778200065.webp", "9789778200065", "سفر التيه", 180, 140m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 246, "شريف ثابت", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وتدور الرواية حول د.حازم أبو زيد الطبيب النفسى الشهير، الذى يقيم فى مدينة سياحية فاخرة بالإسكندرية وبسرد حالة نفسية غريبة وردت إليه من مهندس أحمد خشبة، ذلك المهندس الثرى الذى تربى على البذخ والترف، درس الهندسة فى بريطانيا على يد اشتراكى عتيق علّمه أنه كمهندس لابد أن يطبِّق ما تعلّمه من دينه وهندسته على الفقراء، ولقد حاول ذلك بالفعل ولكنه اصطدم بالروتين الحكومى العقيم الذى منعه من إكمال حلمه.", "/images/products/9789776376243.webp", "9789776376243", "أنــين", 332, 230m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 247, "شريف ثابت", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), ".فى الجزء الأخير من عالم أفضل يبَلغَ الصراع محطته الأخيرة . الثورة تسرى كالنار فى الهشيم، تُحقِق الانتصارات المظاهرات،والفوضى تضرب المُدُن. العالم مُنهَك  ،مُثخنة بالجراح بعد أن نالَت منها الثورة ما نالَتEgy- Nergyو ولكنها لم تنتهِ بعد. مازال أخطر أسلحتها موجودا ً .وعلى وَشك النزول لحلبة المعركة الليلة، تشتبك أشباح الماضى مع أطياف الحاضر فى جولة أخيرة  .من أجل المُستقبل الليلة، تنتهى الحرب، وتُطوَى صفحة القديم من أجل بَعث  جديد .الليلة، يتحدد مصير العالم.. فإما كابوس جديد، وإما عالم أفضل", "/images/products/9789778200072.webp", "9789778200072", "البعث", 444, 300m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 248, "ماجد شيحة", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتحدث الرواية عن النبوءة النبوية برفع القرآن الكريم من المصاحف، لا تتخذ الحدث ذاته كمحور للرواية بل محاولة الانسان بعد اختفاء النص المقدس للبحث عن طريقة لبث منظومته الاخلاقية وايقاف المد المتطرف المنادي بمعارك نهاية الزمان، تنقسم الرواية على راويتين: كاتب مؤمن بالكتابة، وقاتل حكومي يقدس الاوامر والنصوص، وما بينهما تتردد شخصيات الرواية لتحقق أمل الانسان في ايجاد عالم هاديء بلا حروب ولا تكفير.", "/images/products/9789778200485.webp", "9789778200485", "إيلات", 434, 300m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 249, "ماجد شيحة", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتحدث الرواية عن النبوءة النبوية برفع القرآن الكريم من المصاحف، لا تتخذ الحدث ذاته كمحور للرواية بل محاولة الانسان بعد اختفاء النص المقدس للبحث عن طريقة لبث منظومته الاخلاقية وايقاف المد المتطرف المنادي بمعارك نهاية الزمان، تنقسم الرواية على راويتين: كاتب مؤمن بالكتابة، وقاتل حكومي يقدس الاوامر والنصوص، وما بينهما تتردد شخصيات الرواية لتحقق أمل الانسان في ايجاد عالم هاديء بلا حروب ولا تكفير.", "/images/products/9789778200591.webp", "9789778200591", "المعبر", 284, 200m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 250, "فاطمة الزهراء الرياض", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "امرأة من حلم وخسارات وعلاقات لا تستقيم. تعاندها الظروف بين الضغط الأسري والغربة والوسواس والقلق والعمل في تدريس الفلسفة. تلتقي ستيفان، رجل غني وعميق ومختلف عن كل الرجال. لانه لا يعرف نفسه بسبب تخبطه في التوحد في صغره. بين المواجهة والهروب من الامكنة التي تستعصي عن الحياة تعيش وهي تكتب في ذهنها عبر استعارات ومجازات واحداث يومية رواية تسميها \"المختلف\" . انتهت بها المسارات في مدينة براغ بعد ان قررت الهجرة والتبخر على الطريقة اليابانية.", "/images/products/9789778200560.webp", "9789778200560", "المختلف", 258, 180m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 251, "فاطمة الزهراء الرياض", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الكتابة ايضاً كانت لها كمشرط الجراحّ ويجب تعقيم شعورك بالصدق كى تفتح جرحا ما  ...\nعليك كذلك أن تكون دقيقاً ومرهفاً بما يكفى  لتحس بالجثة الممدة امام رحمتك ..", "/images/products/9789776376748.webp", "9789776376748", "تراجيم", 174, 120m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 252, "حسن الحلبى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الشاب السوداني الأسمر النحيل (مفتاح)، وامرأته الروسية البيضاء الضخمة (ناتاشا)، جنبًا إلى جنب مع أكثر رجل في العالم يكره ارتداء الأحذية، ينطلقون في مغامرة مجنونة وغريبة الأطوار: بحثًا عن شيء لا يتسع الغلاف الخلفي لذكره، طبعًا!\n\nهي رحلة عبثية وفانتازية تأخذك إلى عالم لا ندري حقًا إن كان موجودًا، في مطاردة كيان لا نعرف حقًا إن كان حيًا، وسط شخصيات لا ندري إن كان هناك من يشبههم في الواقع!\n\nروايتك كانت مفاجأة حقيقية لي، فقد كتبت بأسلوب جميل وساخر، تحمل في طياتها نفسًا شبابيًا واضحًا، وكتابة حداثية تسعى لتثبت وجودها.\n\n— أمير تاج السر»", "/images/products/9789776376649.webp", "9789776376649", "رجل يكره الأحذية", 166, 120m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 253, "حسن الحلبى", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تبتسم بهدوء كنجمة ..\nأشهدُ أنِّي منذ زمن مسكونٍ بالبُعد ؛ لم أر مثل هذه الابتسامة !\nلماذا يبدو وجهها الشَّبيه بالسَّحاب هذا ؛ قريباً من وجه (سندس) ؟!\nليست المسألة مسألة تشابه في الوجه أو الملامح أو العينين ؛ هناك شيء أعمق ، وكأنّ روحها تشبه روح ( سندس ) ؛ حقًّا ..\nأسحبُ نفساً عميقاً من السِّيجارة :\n ما اسمكِ ؟!", "/images/products/9789776376526.webp", "9789776376526", "مستحيلة", 168, 120m, new DateTime(2014, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 254, "هدي عبد المنعم", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور في إطار اجتماعي نفسي ورومانسي، من خلال عرض علاقة معقدة لشقيقتين، تتعرضان للفقد في مقتبل العمر من ثم أزمات نفسية وحياتية متتالية. الرواية تتناول اضطراب القلق المزمن والرهاب الاجتماعي، وتتعرض للعلاج النفسي بالرقص والحركة. كما تتبنى أفكار إيجابية كملاحقة الشغف والتحقق، وتجاوز التجارب السيئة وتصحيح المسار والمضي قدما.", "/images/products/9789778200843.webp", "9789778200843", "متسع للرقص", 264, 180m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 255, "هدى عبد المنعم", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتعرض «هاجس» للأوهام التى تغلب على النفس وتشغل حيز وهمى من الفراغ، فتدع أصحابها فى متاهات بلا بداية أو نهاية.\nحين تنغلق نفسك على هاجس ، تغمس روحك فيه ، وتقصر أفكارك وتمنياتك وتمحور حياتك عليه، ظناً أن غيره ليس له من سبيل إليك، إلى نفسك وحلمك، رغم أنه أبعد ما يكون عنك، لا تنتمى إليه، إنما ينتمى هو إلى توجسك، تخوفك، ضعفك، قصر بصيرتك، استسهالك، استسلامك، احتياج ملح منك، ورغبة مغلوطة أمارة بالسوء.", "/images/products/9789776376410.webp", "9789776376410", "هــاجس", 266, 180m, new DateTime(2014, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 256, "هدى عبد المنعم", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الحوادث حين تأتي لا تحجز موعدًا؛ تأتي وحسب.. طوال الوقت، لكن ثمة حدث في لحظة ما قد يغير مسار حياة شخص بأكملها!\nأقرب المقربين مُتَهَم بالأذية، الشخص الذي من شأنه ألا يسمح بشيء سيء يحدث لها؛ جربتْ ما كان بمقدوره حين يصد أحدهم في وجهه؛ ضربها في مقتل، قالبًا عالمها رأسًا على عقب!\nهذا النوع من المشاعر لا يمكن التهاون فيه؛ فإما يشد العضد وإما يهد الحيل؛ فلو فعل غريب فعلته بها لما استغرقت في نسيانها عُشر ثانية، أو لعلها ستحتاج إلى مزيد من الوقت، لكن لن يكون لها أثر الفراشة على حياتها!", "/images/products/9789778200034.webp", "9789778200034", "أثر الفراشة", 262, 180m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 257, "محمد الحموي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بعيدا عن الضجيج، مازالت تغلق على نفسها باب غرفتها.\nتجلس أمام المرآة كما اعتادت دائما أن تفعل منذ أن كانت صغيرة.\nتحدق في عينيها. كثيرا ما انتظرت أن تبعث روح في الانعكاس، وأن تقوم صورتها المنعكسة بمحادثتها.\nانعكاس شخصي له القدرة على فك العقد وإتاحة الفرصة أمام صاحبه ليرمي كل ما أنهكه لسنوات، وكل ما حمله في صدره دون أن يستطيع البوح ولو لمرة واحدة كما ينبغي لمن ينبغي.\nلعل بوح النفس أمام النفس هو ما حلم به الكثير منا. أن تتجسد النفس فجأة فيستطيع المرء التعري وبسط الحقائق دون خوف أو خجل.", "/images/products/9789778200362.webp", "9789778200362", "صاحبة المولد", 172, 120m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 258, "محمد الحموى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اد ليسأل هل هذا هو الطريق الذي يبحث عنه ؟ أو الذي أُرسِلَ ليبحث عنه ؟ أهو الطريق الحقيقي المباشر ؟ أقصر الطرق إلى الله ؟ هل فعلاً وصل أبو الحكم إلى الله ؟ كان يريد جواباً لا لينقله للعجوز فقط لكنه يريد جواباً لنفسه التي كُشِفَ عنها غطاء ركودها و اشتعل حراكها و غليانها، و ظهرت تساؤلاتها الواضحة تسعى دون تراجع للحصول على ما يشبعها.\n تحول فجأة إلى مراقب منفصل غير منغمس أبداً فيما ذاب فيه الرجال حين انسابوا مع الكلمات التي يقولها المنشد أيّاً كانت حتى لو كانت كفراً صريحاً دون أن يعوا ما الذي يقوله، كان يستطيع ملاحظة ذوبانهم و ميلان رؤوسهم المتشابه مهما تراوحت معاني الكلمات، لم يكونوا ليعوا شيئاً مما يقرأ على مسامعهم أو هذا ما اعتقده", "/images/products/9789776376472.webp", "9789776376472", "الزحف نحو السماء", 194, 140m, new DateTime(2014, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 259, "وائل عبد الرحمن", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أكثر ما يزعجني، هو كل ما مررت به في حياتي.\nأكثر ما يزعجني، هو التحدث أمام أشخاصٍ لا أعرفهم.\nأكثر ما يزعجني، أن يطَّلع هؤلاءُ الأشخاصِ على أعماقي بكل ما فيها.\nأكثر ما يزعجني، أن أموت.\nأكثر ما يزعجني، أن يجتمع كل ما سبق في مشهد واحد.\nإذًا.. فلنضع هذا على ذلك ونقلب قليلاً، وأنتحر بعدها، لتكون آخر لحظات الإزعاج.", "/images/products/9789778200041.webp", "9789778200041", "أخر لحظات الإزعاج", 174, 120m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 260, "وائل عبد الرحمن", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الـنـدم سكّين بارد يسلخك حيا، دون امتلاك مميزات البنج، أو رفاهية الموت هربا..\n\nوالدبّ الملطّخ بدم صاحبه، تبددت ابتسامته، وتدلى فكه، وجحظت عيناه..\n\nوساراماجو حدّثنا أن الفوضى هي نظام، لم تُفك شفرته بعد..\n\nوأفعالك واختياراتك؛ ما بين كش ملك وبين تقهقر، تعزف السيمفونيات بين لحن ونشاز..\n\nوالمكان يرسمه الإنسان، والزمان هو لغز الألغاز..\n\nوترجمة كل ما سبق تجدها هنا بالداخل..\nفي راس شيطان", "/images/products/9789776376670.webp", "9789776376670", "راس شيطان", 224, 150m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 261, "سامية عياش", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كانت جبينه الذي قبلته باردًا كالثلج، لامعًا كشمعة ناعمة، ثم اجتاحها شوق جعلها تقبل وجهه كله.\n\nمررت شفتيها على جسده كعاشق تاقت روحه إلى الامتلاء بالحب.\n\nكان كل ما فيها يستشعر جسده، تفكّر كم مرة عانق التراب دون أن يذوب فيه حقًا، جسدُه الذي احتضن الزنزانات رغم ما قد تظنه القلوب من أن الزنزانة تحوي ولا تحتوي.\n\nجسده الذي لم يذرف الدموع إلا بالدم، ولم ينطق إلا بلغة الصبر والصمت؛ جسد ذلك العصي الذي فقد ماء طفله، لكنه بقي يحلم أن يكون له... يداها تتحسسان طريق شفتيها قبل أن تمرا على اللَّون الأبيض البارد، يداها المرتجفتان الخائفتان من أن تخدش فيه شيئًا، يداها اللتان كانتا حلمه لو كان حيًا.\n\nظلت تتحدث أمام جثته كما لو كان يقظًا، دون أن تبكي، مدفوعة للحكي لا للبكاء، فلبكاء وقت لم يحن بعد.", "/images/products/9789776376762.webp", "9789776376762", "تكاد تضىء", 278, 200m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 262, "محمد كامل", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "فى ليلة ممطرة تصاعد الخلاف بين غادة وزوجها بعد تناولها عدة أقراص مهدئة وتتطور الخلاف الى شجار فقتلته دون قصد بسكين..  فلم تجد ما تفعله غير أن تهرول بملابسه المتسخة بدماء زوجها إلى جارها أدهم بعد منتصف الليل\nساعدها أدهم فى التخلص من جثة زوجها...\nوجعلها تقيم مع جارتهالعجوز حتى تهدأ أعصابها لأنها كانت تخاف من العودة لشقتها\nلكن جاره  القاطن فى الشقة العلوية شاهده وهو يضع الجثة فى السيارة  وتتبعه وعرف ما فعله  وظن اانه القاتل بالاتفاق مع زوجة القتيل  وهدده بفضح آمره", "/images/products/9789778200942.webp", "9789778200942", "بعد النهاية", 214, 140m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 263, "محمد كامل", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عن شكل الحياة فى مصر وملامح البلد فى الفترة من أخر  الحملة الفرنسيه مروراً بفترة حكم، محمد على وصعوده للحكم وحتى الطاعون الذى أصاب البلاد عام 1835. من خلال حياة أسرة من الجد للابن والأحفاد. الجد الذى كان مشارك للمقاومة ضد الحملة الفرنسية.ومشاركة بطل الرواية فى الحرب الوهابية، ومعاناته خلالها، ومعاناته من مرض الطاعون الذى اجتاح البلاد والعباد بعد عودته بسنوات، نهاية بوفاة ابنته الصغرى به فى أخر الرواية، مروراً بالتدابير التى اتخذتها الدولة للسيطرة على الوضع.ومعاناة البلاد وعامة الناس من ظروف البلاد فى تلك الفترات.. وطريقة حياتهم.. والقهر الذى مروا به وسط أفراحهم وأحزانهم", "/images/products/9789778200515.webp", "9789778200515", "خريف المحروسة", 318, 230m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 264, "محمد فوزى عبد الرحيم", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اشتهرت قبل أن أعتاد على اسم الولادة بفاتنة المجالس، حتى ولم أكن قد أكملت العاشرة من عمري، فجمالي الطاغي كما سمّاه جلالة الملك فؤاد الأول في المرة الأولى التي عرضني فيها أبي على بصر معاليه، كان سرًّا من أسرار شعوري المبكر بنشوة غريبة تغزو روحي كلما خلَبت عيون من حولي منحنيات جسدي أو التواءات شعري المنسدل.\nلسنوات ظننت انها نشوة السعادة الابدية.\nغير انها لم تكن الا سكرة من سكرات الموت المحتوم.", "/images/products/9789778200409.webp", "9789778200409", "أفندار", 378, 240m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 265, "مريم سبع", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا بأس حبيبي.. هذا العالم لا يستحقّ شيئا من دموع أو أسى.\nهذا العالم الذي يرسل بالشمس وأسراب الطيور كلّ صباح ويسترجعها كلّ مساء، ولا كأنّه ينطوي على كلّ هذا الكمّ من المعاناة.. أحكام مؤبّدة بالسواد والسكوت، والصمت والسّكون، والفقر والجنون، وأسقام وشجون، وهذا جميل بلا تعب، وذاك قبيح بلا ذنب، وهذا سعيد وكلّه شرّ، وذاك شقي وجلّه خير، وهذا يعيش حتّى يموت، وذاك يموت قبل الحياة..\nلقد فهمت هذا العالم مذ تفطّنت إلى فوائد الخلّ وأضرار السّكر.. نحن لسنا هنا كي نستمتع بالحلاوة، نحن هنا كي نتجرّع المرارة، فإن أطعنا الحلو وعصينا المرّ، فإنّ العاقبة لن تسرّ.\nلذا ما عاد يمضّني بعد هذا الفهم شيء، ولا حتّى أنّنا افترقنا.. وبخصوص أنّي أمسيتُ على يقين، أنّه اللقاء.. دنا من أن يحين..", "/images/products/9789778200119.webp", "9789778200119", "إذا زاد الود", 232, 150m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 266, "طنطاوي عبد الحميد طنطاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ثورة متأججة ، قينمو فكر فقر ، ويتناسى الفقير والمحتاج الثورة عندما تأتيه الثروة ، فيغض الطرف عما يقترفه هو أو الآخرون من أخطاء ، يرصد وقائع السقوط ولكن لا يبالي ، حتى يقع بين براثن الظلم والقهر ، فيقام عليه الحد على الملأ رغم عدم ارتكابه للخطيئة ، يتذكر بأنه ثائر ، تعود إليه ملامح الثورة القديمة ولكن مشبعة بالخوف ، هل يستطيع أن يصمد ويجاري فكر الثوار أم يتوه في زحام الجماهير المحتشدة ؟ ولا يستطيع أحد أن يعرف موطأ قدمه ، فأين ذهب الثائر ؟", "/images/products/9789778200584.webp", "9789778200584", "سجين الوهم", 352, 240m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 267, "طنطاوي عبد الحميد طنطاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عندما يداعب الأمل المحرومين ...تنهمر سيول الخير والنعمة في أموال لا حصر لها ، هل يستطيع المال تغيير الصورة القاتمة ؟ هل الثراء نعمة أم نقمة ؟ لا ثقافة ولا فكر ولكن جها متفشِ يستطيع أن يشوه الصور الجميلة التي يمكن للإنسان رسمها عبر مخيلته وإبداعه ، يتباعد الأهل وتثار نزعات طائفية مقيتة ، الكل يتخوف حتى بين من جمعت بينهم أواصر القريى وصلة الرحم ... حكاية قرية أصابها وابل الخير", "/images/products/9789778200393.webp", "9789778200393", "شق الجبل", 310, 215m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 268, "مى سلام", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حين كان عدنان يتخذ من حديقة أتاتورك في أسطنبول رفيقا دون البشر يلجأ إليه لينسى الألم، الذي لم يبرح قلبه منذ سالت دماء حبيبته على صدره، لم يكن يتخيل أن الحديقة ذاتها سترسل له طوق النجاة من أجل حياة جديدة، ينبت فيها الجمال من بين قسوة الحروب ولوعة الفراق.", "/images/products/9789778200454.webp", "9789778200454", "اتاتورك", 244, 150m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 269, "سميح فتحي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "سيسألونك كيف تعرفُ أن حبًّا ليس حب، أو كيف تُمتحَنُ القلوبُ قبيل مفترقِ الطريق، قل هل لَهَوتَ بذاتِ بحرٍ بين بعضِ الأصدقاء،هل حين غابَ وجدْتَ روحَكَ بين منتصفِ الحريق، قل هل مشيتَ على الصحاري وفي انتقامٍ للعطش، ثم اكتشفْتَ بذكرك اسمٍ أن قلبَك في الغريق، يا قتلَ روحٍ دون حبٍّ تمضي بالعمرِ القصير، يا دفنَ نفسٍ في الحكايةِ حين ينطفئُ البريق، يا أيها العشاقُ تبًّا سوف تُختطَفُ الحياة، ولسوف نمضي بذاتِ نهرٍ؛ إذ نلاقي جفافَ ريق، قُل مَن سيدفعُ بالمقابلِ حين يندلعُ المشيب، قل من يعوِّضُ حين نكبرُ بعضَ عمرٍ قد أُريق، اليومَ هيَّا انهالوا سبًّا فوق جمجمة الرجوع، الخوفُ يمضي من طريقٍ والمشاعرُ من طريق.", "/images/products/9789778200478.webp", "9789778200478", "ريسال", 310, 215m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 270, "ريم مراد", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كثيرون يربطون بين الاجتياح والاستعمار والحروب والمآسي، لكن اجتياحى مختلف،الاجتياح العاطفي، تلك العلاقة التي تخترق كل خطوط دفاعنا الفطري وتجتاح قلوبنا، هذه المشاعرالتي تهزنا من الداخل فتزلزل دنيانا وتجعل لبوصلتنا اتجاهًا واحدًا، ألا وهو الشخص الذي اجتاح قلوبنا وأرواحنا، هذا الشخص الذي بوجوده بجانبنا لا نحتاج لأي شيء آخر في الحياة.", "/images/products/9789776376946.webp", "9789776376946", "إجتياح", 265, 180m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 271, "ياسمين ثابت", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رواية واقعية عن فتاة نصف سورية ونصف أمريكية .. اجواء غربية جمعت بين والدها السورى المسلم وأمها الامريكية المسيحية فى زواج لم يدم .. لفظ ثلاثة اطفال .. هما مازن, فاطمة واخيرا آشيـا ...\nعاشوا طفولة قاسية بائسة بين اب شرس فاسد وام صابرة لاجلهم ..\nحادث سرى يجعل اباهم يعود بيهم إلى سوريا فجأة ليبعدهم عن امهم وتنتهى علاقتهم كلياً بها لسنوات ..\nالطفولة الجافة التى عاشوها فى رعاية اسرة الاب الذى رماهم هناك وعاد إلى حضن امريكا بحجة رغبته بتعليم اولادة الاسلام", "/images/products/9789776376465.webp", "9789776376465", "آشـــيا", 370, 240m, new DateTime(2014, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 272, "فائقة قنفالي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"مجرد ألم\" لفائقة قنفالي تناقش قضايا إنسانية واجتماعية عميقة بأسلوب مؤثر، مستعرضةً معاناة الشخصيات من الألم الجسدي والنفسي والاجتماعي في حياتهم اليومية. تتناول المجموعة القصصية تجارب مختلفة، بدءًا من القهر الأسري والاعتداءات الشخصية، وصولًا إلى تجارب الحب والخيانة والتضحية.", "/images/products/9789778202915.webp", "9789778202915", "مجرد ألم", 112, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 273, "عمرو العادلي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نا لا أجيد الاختصار، ولستُ بارعًا في ربط الأفكار، لا يمكنني التحدث بانتظام عن أي شيء، ولا أعرف كيف نما كل هذا الكُره في نفس حلمي تجاهي، فقد قال لي ذات مشادة كلامية «أنت شخص عبيط وليس لديك أي خبرة بالحياة» كيف يقول ذلك وأنا موظف محترم؟ أرى أن طاعة رؤسائي واجب مقدس، أبتسم دائمًا ولا أنسى نصف انحناءة أمام الزبائن كما أوصاني أبي، أفعل باقتناع ما يجعلهم يعتقدون أنهم أذكى مني، وإلا فلماذا أنحني إن لم يكونوا صنفًا ممتازًا من البشر؟ مؤكد مكتوب أمامك في الأوراق أن أبي هو الذي عيَّنني في هذه الشركة العتيقة، ثلاثون عامًا وأنا أتحدث همسًا إلى الزبائن، أعرض عليهم فضائل شراء السخانات حتى في فصل الصيف.", "/images/products/9789778201246.webp", "9789778201246", "بائع السخانات", 190, 140m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 274, "سارة سيف", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كانت الحياة هادئة تمامًا داخل جدران بيت ثُريا، هادئة كشخصيتهما معًا، غرفتان وصالة في شقةٍ صغيرة بحي المنيل الهادئ، في زاوية بالصالة، تضع الجدة ماكينة الخياطة ماركة \"سنجر\"، على طاولة خشبية لها أربع عجلاتٍ صغيرة، تجرها أمام الكنبة الكبيرة وقتما رغبت في استعمالها، وتعيدها لمكانها بعد تغطيتها بمفرش من تطريزها أيضا، تلك الكنبة التي اشتراها الجد عبد الله في أول زواجهما وتعتز بها إلى الآن، تغير قماشها، ولا تفرط فيها، \"فيها ريحته\". دائما ما تخبر ندى بذلك، وضعتها بالقرب من بلكونة بحري واسعة \"هواها يرد الروح\" يغبطهما عليها الجيران، ويأتي بعضهم يجلسون معها فيها لشرب الشاي بالنعناع الذي تزرعه فيها، مستمتعين معها بنسمات الهواء الرطبة المختلط برائحة زرعها.\n ومع الهواء، فالشمس تحب بيت ثريا أيضا، تزوره ساعات خاطفة في ظهر اليوم، تُطهر لها البيت وتزيده دفئًا على دفء محبتها.", "/images/products/9789778201130.webp", "9789778201130", "تندر", 160, 120m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 275, "سندس الحسيني", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تداعت الصور ورائحة المطار الخانقة وقفزت إلى ذهني صورتي وأنا أمسكها بيدي لتُسرع الخطى بطريقةِ سيرها الطفولية نحو الطائرة بعد أن عرفت أنني لست على قوائم الممنوعين من السفر.. حين علمت أنني سأتمكن من الهروب.. لولاها ما هربت.. لولاها ما تعبت.. ولولاها ما أحببت الحياة.", "/images/products/9789778200379.webp", "9789778200379", "وتغير لون السماء", 136, 120m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 276, "إيناس التركي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وقف وسط الحقل يحاول فك شفرة الكلمات التي غزت مِسْمَعَيْه من كل اتجاه. بينما هو يحاول فهم حديث الأشجار، دنا منه صاحب الكلمات. وضع يده على كتفه، فقفزت الغيمة فجأة. ربت الصبي عليها فاستكانت. ابتسم صاحب الكلمات للصبي وهو يخاطبه: \"كنت أنتظر حضورك. أرسل إليَّ الغلام صاحب السحاب خبرًا مع سحابة بأنك قادم. تعالَ معي لتشاهد الأشجار قبل أن تتخيَّر كلماتك منها. لديَّ شجرة تتقن لغاتٍ عدة، من يقطفْ منها ويأكل من كلماتها يبدُ ذكيًّا جدًّا للمستمعين، لكن عليه بذل جهد مضاعَف حتى لا تتداخل الكلمات وهو يتحدث فتختلط اللغات. ساعتَها لن يفهم حديثَه أحد، ويصير أضحوكة. قد يدهشك عدد الذين يختارون الأكل من ثمرها رغم مشكلاتها. أعتقد أن رغبتهم في الظهور بمظهر الأذكياء تفوق اهتمامهم بالتواصل والفهم، لكن لا بأس، فنحن بحاجة للضحك من حين إلى آخر! لديَّ شجرة أخرى لا تثمر سوى كلمة واحدة فقط. تختلف الكلمة باختلاف من يقطفها. تعرف الشجرة ما بقلب كل مَنْ يقترب منها، فتثمر الكلمة المناسبة لما يحمل هو بداخله. يفضِّل البعض هذه الشجرة لسهولة حديثها. كلمة واحدة، لا يرددون غيرها، ولا يغيرونها أبدًا، مهما حاولْتَ إقناعهم بأن هناك كلمات ولغات أخرى كثيرة. تتصلب ألسنتهم وأدمغتهم عندها، وكفى! لديَّ شجر مشاغب بعض الشيء، لكنه مُسَلٍّ. يطرح أحاجي من كلمات غير مكتملة، تركِّبها وتصل بعضها ببعض كيفما شئتَ، لتلائم أي موقف تواجهه. معظم من يفضلون ثمارها هم من المغرمين بلعب السياسة أو الفلسفة\"", "/images/products/9789776376939.webp", "9789776376939", "من هنا تمر الأحلام", 90, 120m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 277, "عبدالرحمن الخميسي، أحمد الخميسي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نحن إزاء كتاب غريب من نوعه، يضم بعضًا من القصص القصيرة الجميلة، لثلاثة كُتّاب تفصل بين كل منهم نحو ثلاثين عامًا، لكن تجمعهم أواصر أسرة واحدة: الجد، والابن، والحفيدة. الشاعر القاص المعروف عبد الرحمن الخميسي، جذر هذه الشجرة المورقة، والابن أحمد الخميسي، وأخيرًا الحفيدة آنا أحمد الخميسي. وسأترك القصص لتحدّث القارئ بنفسها عن مواطن جمالها وفتنتها. وإذا نحينا جانبًا موضوع العائلات التي تسري فيها الموهبة من جيل إلى جيل، فإن سؤالاً آخر يطرح نفسه: هل يشتمل توريث الموهبة على توريث القضايا ونقاط الانطلاق الفكرية والشعورية ذاتها؟ يبدو ذلك! ففي كل تلك القصص -رغم مساحات الزمن الفاصلة- ثمة اهتمام بأوجاع الناس، في قصة \"النوم\" للخميسي الكبير، وقصة \"بط أبيض صغير\" للخميسي الابن، وقصة \"الأيدي\" لآنا الخميسي. يتصدر الإنسان كل ذلك الإبداع بطرق وأشكال مختلفة ووسائل أدبية متعددة. إنه كتاب فريد تصدره معًا أسرة عرفت بقدراتها ومواهبها وإخلاصها للوطن والفن، ولعلي أتوقف بانتباه خاص أمام قصص آنا ، ليس باعتبارها الأصغر في هذه العائلة ، ولكن لأن لديها خصوصية أراها متفردة، حيث العيش في عالمين يعزز كلاهما لماحية رؤية أخص خصوصيات الآخر ، متزودة بأدوات فنية من تراث أدبي عالمي عريق تنتمي له أصولها ، وضاربة في رهافة العمق حيث تمد جذورا جديده فتية ، في أرضنا .\nمحمد المخزنجي", "/images/products/9789776376700.webp", "9789776376700", "الأجيال الثلاثة", 152, 120m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 278, "تسنيم فهيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أدخل غرفة أمي وأُخْرج أحشاء الدولاب، فلا أجد شيئًا. أعود لغرفتي وألاحظ أن رأس الأباجورة يُشبه القبعات. أنزعها عن هيكلها وأضعها فوق رأسي. أثبّتها في شعري ببعض مشابِك الغسيل. أقف أمام نفسي في المرآة. أثني على مظهري الذي سيجعل «الكل يتجنن عليّ». أذهب مرة أخرى لغرفة أمي بحثا عن المفتاح. أخرج للشارع الذي لم أعد أتذكر ملامحه. أخطو خطواتي الأولى في الحارة. أنتظر أن يراني الكُل ويتجننوا عليّ.", "/images/products/9789776376427.webp", "9789776376427", "لوح رخام ابيض", 160, 120m, new DateTime(2014, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 279, "سارة أبو العز", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "شيء غريب يسيطر على العقل والروح الداخلية معًا، شيء يشبه الفوبيا، الفوبيا من اللاشيء. شيء يشبه العدم، أو خمول ما داخلنا تجاه كل شيء في الحياة، نتيجة بُعد كل ما نتعلَّق به، وذلك بعد رسم حياتنا به. حكاياتنا دائمًا تتجدد، لن تسير على نمطٍ واحدٍ، يمكن أن تكون سعيدة، وأيضًا يمكن أن تكون حزينة، لكنها بالنهاية لن تقف أبدًا. والآن في تلك الغرف السرية الكثيرة سنعرف أن الحياة خُلِقت بأشكالها المختلفة، بألوانها المختلفة، منها الفاتح والداكن، ولن تكون بيضاء دائمًا، أو سوداء دائمًا، ستأتي أيامٌ تلاحظ فيها أن هناك مواقفَ واختبارات تميل إلى اللون الرمادي، وذلك هي سنَّة الحياة حتى تنعدل الموازين الحياتية.", "/images/products/9789778201512.webp", "9789778201512", "غرفة سرية", 224, 140m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 280, "ندى ترك", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لحظة.. هي لحظة واحدة فاصلة فارقة في حياتك.. اللي بتواجهي فيها نفسك وبتكسري القيود اللي رسمتيها لنفسك من سنين... اللحظة دي هي اللي بتوصلي فيها للحقيقة.. لإنك تقدري.. تعرفي.. تستحقي.. اللحظة دي هي بداية تقويم.. بداية حياة جديدة.. لشخص جديد.. بداية انقشاع الغيوم.. واكتمال الرؤية.. لحياة أحلى.. حياة بوعي.. من غير نكد", "/images/products/9789778201499.webp", "9789778201499", "أبو النكد", 232, 150m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 281, "تامر أحمد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ومن هنا بدأت الكارثة.. عرض الناس حيواتهم على (السوشيال ميديا) كعرض الملابس الداخلية على منشر الغسيل، وفرحوا بلعبة (الرأي والرأي الآخر) فقالوا (الرأي) ولعنوا أعضاء (الرأي الآخر). تعاظمت ذواتهم، وصار كل منهم عالما مفتيا أديبا سياسيا اقتصاديا مدربا لكرة القدم، والملايين غيره من الأنعام بل هم أضل سبيلا. والسؤال هنا: لماذا يقبل الناس مثل هذه التدخلات من الآخرين في حياتهم الشخصية؟ ولماذا لا تكون إجابتهم دائما على مثل هذه التدخلات هي الإجابة العظيمة السحرية.. \"انت مالك؟\"؟", "/images/products/9789778200836.webp", "9789778200836", "مالك ... مفيش", 232, 150m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 282, "تامر أحمد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من منا لا يعرف الحصان الأكثر شهرة في التاريخ «حصان طروادة » والذي استُخدمَ في الحرب الضروس التي قامت قديمًا بين إسبرطة وطروادة، واستمرّت قرابة الأعوام العشرة .. لكن التاريخ غير المنصِف لا يُبرز لنا دور الحِمار في هذه القصة .. والحق أن القصة بها أكثر من حمار ..\nفي هذه القصة سمح محروس للعديد من الأحصنة المماثلة بالدخول إلى حياته .. وكانت النتيجة الحتمية بتدمير حياته كليًّا .. إلى أن مَلّ من لعِب دور حمار طروادة، وقرر أن يقلب الطاولة على الجميع ويلعب هو دور الحصان ويَجُرُّ الآخرين نحو مصيرهم المحتوم .. فهل سينجح في التحول من حمار إلى حصان؟\n الرأي .", "/images/products/9789778200553.webp", "9789778200553", "حمار طروادة", 224, 150m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 283, "تامر أحمد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "زمان كان الفيسبوك وسيلة سريعة للتعارف أما الآن فأصبح وسيلة للخناق والتخاصم واللعن والسب...\nويبدو أن اسم الفيسبوك قد سمي بهذا الاسم لأنه يستخدم في نشر الآراء المختلفة مما يخلق مساحة من الاختلاف في الرأي بينك وبين أصدقائك \" فَيَسِبُّوك ويشتموك\"، وفيما يلي نصائح هامة للتعامل مع فيسبوك في زمن الثورة التي أصبحت تغلف كل تفاصيل حياتنا.\nكيف تخسر أصدقاءك وأحبابك في ستة بوستات:\n1-اكتب بوستات كتير .. هاجم كل المعارضين لك .. خليك وقح ولا يهمك .\n2- أدخل علي كل صفحات الآخرين وتابع كل ما يكتبوه علي صفحاتهم .. علق عليه .. هايمسحوه .. علق تاني .. هايمسحوه .. اكتب تاني وتالت لحد ما يزهقوا .\n3-هايردوا عليك ويهاجموك .. عِش في دور الشهيد .. احذفهم من قائمة أصدقاءك .. هايضيفوك تاني .. تجاهل الإضافة .. فالاختلاف في الرأي يفسد للفيسبوك قضية .\n4-اكتب بوست تاني واشتم الأصدقاء اللي حذفتهم من قائمتك .\n5-هايبعتولك رسالة .. ماتردش عليهم .. هايبعتوا تاني .. احلق لهم .. اعمل لهم بلوك حتي لا يزعجوك مرة أخري.\n6-بس خلاص .", "/images/products/9789776376960.webp", "9789776376960", "لقمة الفاضى", 148, 120m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 284, "تامر حسنين", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الكتاب يناقش مفهوم الخيانة بشكل عام والخيانة الزوجية بشكل خاص من المنظور النفسي والسيكولوجي ... ويستعرض بعض الحالات الحقيقة كنموذج للخيانة الزوجية.\nيشرح الكتاب تعريف الخيانة بمفهومها الواسع وأسبابها وأنواعها ويستعرض بعض الإحصائيات والدراسات. كما يشرح الإجراءات العلاجية للطرفين للوصول إلى التعافي من أثار الخيانة على الشريكين.. من مرحلة إكتشاف الخيانة إلى مرحلة بناء الثقة من جديد والوصول إلى التسامح.\nكما يشرح الكتاب التأثير النفسي للخيانة على الشريكين وعلى الطرف الثالث.", "/images/products/9786339957512.webp", "9786339957512", "خنتك ليه", 328, 250m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 285, "ألمار نيفلينج", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"إنه جنون كُرة القدم، وكيف يعيشها الناس في ليفربول، وجميع مُشجِّعي ليفربول حول العالَم. إنه ليس ناديًا عاديًا أبدًا، إنه نادٍ مُميَّز\".\n-يورجِن كلوب\n\nصَدَم قرار يورجِن كلوب بمُغادرة ليفربول بعد تسع سنوات مُذهِلة مُجتمع كُرة القدم. فقد كان لفطنته التكتيكيَّة، ومهاراته التحفيزيَّة، وقُدرته على تطوير المواهِب الشابَّة دور أساسي في عودة ليفربول كفريقٍ كبيرٍ في كُرة القدم الإنجليزيَّة والأوروبيَّة.\n\nقبل أن يُحدِث ثورة في اللعبة في إنجلترا، أطاح المُدرِّب الاستثنائي بمُفرده بالنظام التقليدي في الدوري الألماني، حيث قاد بوروسيا دورتموند من العدم إلى الفوز بلقب الدوري الألماني مرَّتين مُتتاليَتين. ثُم، وفي عام (٢٠١٩)، حفر اسمه في كُتب التاريخ بإعادة ليفربول إلى المجد في دوري أبطال أوروبا، مُنهيًا انتظار النادي الذي دام لأربعة عشر عامًا للفوز بلقبٍ أوروبي كبير. وكان كلوب العقل المُدبِّر وراء تحقيق ليفربول للقب الدوري الإنجليزي المُمتاز في موسِم (٢٠١٩ – ٢٠٢٠)، وهي عودة مُرحَّب بها إلى قمَّة كُرة القدم، مما رسَّخ مكانته كأسطورةٍ في تاريخ النادي.\n\nوحتى بعد رحيله، سيظل كلوب يحظى بالاحترام والتبجيل كمُدرِّبٍ تكتيكي بارِع له فلسفته الفريدة في اللعب. وسيظل إرثه بين لاعبيه هو شغفه ومهارته في إدارة الفريق، وسيظل معشوقًا إلى الأبد بين الجماهير لسحره، وخفَّة ظلّه، وكُرة القدم المُثيرة التي قدَّمها على أرض الملعب.\n\nهذا هو الاحتفاء النهائي بيورجِن كلوب، بطبيعته المتواضِعة، وعبقريَته الكرويَّة.", "/images/products/9786339957505.webp", "9786339957505", "يورجن كلوب", 472, 350m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 286, "مارك غريني", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كورتلاند جنتري رجل طيب، لكنه قاتل ماهر.\nفي الظلال، يُعرف باسم \"الرجل الرمادي\". إنه أسطورة في عالم العمليات السرية، يتنقل بصمت من مهمة إلى أخرى، ينجز المستحيل ثم يتلاشى دون أن يُلاحَظ. ودائمًا ما يُصيب هدفه. دائمًا.\nلكن هناك قوى أكثر فتكًا من جنتري في هذا العالم: قوى مثل المال والسلطة. وهناك رجال يرون أن هذه هي العملة الوحيدة التي تستحق النضال. وفي نظرهم، أصبح جنتري لم يعد ذا فائدة.\nلكن كورت جنتري سيبرهن أنه بالنسبة له، لا يوجد مجال بين القتل من أجل الكسب والقتل من أجل البقاء على قيد الحياة…", "/images/products/9789778201253.webp", "9789778201253", "الرجل الرمادي", 416, 390m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 287, "مارك غريني", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما القتل إلا وظيفة كورت جنتري، لكنه يتحول لمسألة شخصية في الجزء الثاني من رواية الرجل الرمادي لصاحبها مؤلف النيويورك تايمز الأكثر مبيعًا مارك غريني.\nقبل أربع سنوات تعرّض كورت جنتري للخيانة من قِبل رؤسائه في جهاز \"السي آي ايه\" وكي ينجو بحياته لم تكن أمامه سوى التضحية ببعض زملائه. الآن باعتباره قاتلًا محترفًا معروفًا باسم \"الرجل الرمادي\" فهو يكسب عيشه من تصفية آخرين، لكن حين يظهر فجأة زميلٌ قديمٌ له ظنّه ميتًا يطارده ويريد تجنيده لصالحه، تنقلب حياته الدموية لشكل تراجيدي بائس.\nما يريده الزميل القديم من الرجل الرمادي تحويل عملية اغتيال لاختطاف مما يجعلها شبه مستحيلة، لكن المهمة الأصعب هي محاولة إعادة انتمائه لجهاز السي آي ايه بعد انقلابه عليه.\nوهكذا بين مافيا الروس التي لا ترحم وتريد خدماته القتالية من جهة، وبين خطط واستراتيجيات أجهزة الأمن الأمريكية من جهة أخرى، يشعر الرجل الرمادي أنه ينازع فصيلين داخله طوال مهمته، وكي يخرج من هذه المعمعة سليمًا أو حيًّا عليه أن يُريق الكثير من الدماء.", "/images/products/9789778202656.webp", "9789778202656", "الهدف", 540, 390m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 288, "فاطمة المهدي", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب سيكون دليلا لك للتعامل مع شريكك .\nستتعلم معه التالى بخطوات بسيطة :\n- كيف تفهم احتياجك وتعبر عنه وكيف تشبع احتياج شريكك.\n- كيف تتحدث إليه.\n-ما يفضل أن تقوله وما يجب أن تتجنب قوله.\n- وإن حدث بينكما خلاف ما هى الاستراتيجيات المتبعة لحل هذا الخلاف.\nوقبل كل شئ سنفتش معك قليلا فى أعماقك لأن مفتاح نجاح علاقتك مع شريكك قد يكون بداخلك أنت.", "/images/products/9789778200690.webp", "9789778200690", "كبسولات زوجية", 288, 190m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 289, "نسمة مدحت", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كتاب يجمع معظم الأقوال والمثل الشعبية التي تناقلتها الأجيال، حيث يقوم بوصف معانيها وأصولها مع شرحها، ويربطها بالأحداث اليومية في الحياة.", "/images/products/9789778202397.webp", "9789778202397", "ستي قالتلي", 168, 125m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 290, "مرفت أبو عوف", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "Dr. Mervat Abou Oaf chronicles the journey of Egypt’s film industry from the days of its commencement to the contemporary era of digitization and streaming platforms, all while painting a better, brighter, and bigger picture of what the future could entail.\n\nThe book maneuvers around significant dates and milestones, highlighting Egyptian cinema's cultural, political, and economic importance.\n\nThrough the lens of expert interviews, Dr. Abou Oaf examines regulatory frameworks operating backstage and maps out what’s required to sustain and develop a thriving industry, proposing a regulatory model that embraces economic prosperity, cultural values, and industry independence.", "/images/products/9789778201741.webp", "9789778201741", "Art of fantasy", 204, 150m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 291, "Rania Sabry", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“Curses can turn into blessings, though not always will\nthe timing be so convenient!”\nAlthough this period has been stressful for everyone.\nIt has also given many of us the time to reflect on our lives, relationships, goals, and make new plans for the future.\nMany have learned how to be more thankful and empathetic – In other words, putting aside that many have lost loved ones, this period seems to be a blessing in disguise for many.\nHappiness lies in self love and self care.\nThe challenge lies in building the capability\nto break all the barriers within yourself\nthat prevent you from seeking the love you deserve.", "/images/products/9789778201055.webp", "9789778201055", "Wellness", 258, 240m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 292, "ربعي المدهون", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يبحث الكاتب والروائي والصحفي الفلسطيني ربعي المدهون عن كيفية استهلال روايته التي يحاول أن يروي فيها حكايته هو وعائلته، تلك العائلة التي عاصرت النكبة، ومنذ ذلك الحين أخذوا يتنقلون من مدينة إلى أخرى، ومن بيت إلى آخر، خائفين من الظلام الذي تخلفه الحروب، متحسرين على وطن ضائع، صابرين على فراق وغربة امتدت أعوامًا وأعوامًا، حتى كاد بعضهم ينسى صوت أقرب الناس إلى قلبه.\n\nيبدأ ربعي روايته بيوم مولده، ويُعرّفنا على شجرة عائلته التي تبدأ بجده سليم، مرورًا بوالده وأعمامه وزوجاتهم، حتى أخيه الصغير راسم.\n\nكيف نشأ ربعي في مدينة حلّت عليها الحرب، وفي عائلة من النازحين؟\nهل وحدها الحرب هي التي فرّقت عائلته، أم أن الفراق حتمي لا بدّ منه؟", "/images/products/9789778202779.webp", "9789778202779", "طعم الفراق", 300, 230m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 293, "مرفت ابو عوف", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تؤرخ د. مرفت أبو عوف في هذا الكتاب المرجعي رحلة صناعة السينما في مصر منذ بدايتها وحتى العصر المعاصر، عصر الرقمنة ومنصات البث، كل ذلك مع رسم صورة أوسع وأفضل وأكثر إشراقًا لما يمكن أن ينطوي عليه المستقبل. يناور الكتاب حول التواريخ والمعالم الهامة، ويسلط الضوء على الأهمية الثقافية والسياسية والاقتصادية للسينما المصرية.\nفمن خلال مقابلات مع عدد من أهم خبراء الصناعة والثقافة في مصر، تفحص الدكتورة أبو عوف الأطر التنظيمية التي تعمل وراء الكواليس وترسم خرائط لما هو مطلوب للحفاظ على صناعة مزدهرة وتطويرها، كما تقترح نموذجًا تنظيميًّا يحتضن استقلالية الصناعة وازدهارها التوعوي السياسي والاقتصادي والارتقاء بالقيم الثقافية والأخلاقية.", "/images/products/9789778202472.webp", "9789778202472", "فن الخيال", 170, 175m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 294, "حسام مصطفي ابراهيم", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هنا ستجد خليطًا من الشجاعة والجُبن، الضحك والبكاء، الذكاء والحُمق، المرونة والجمود، القضايا العامة والحكايات الشخصية جدًا، ستجد العربية الفصحى والعامية المصرية، النصوص الطويلة والعبارات القصيرة، النثر والشِعر، كلامًا عن الحب، الكراهية، الكفاح، اليأس، الأمل، العائلة، الرفاق، الشوارع، الأغنيات.. لأن الإنسان في النهاية هو مجموع كل هذا وثمرته، ربما أكون قد بالغتُ أحيانًا أو تطرّفت، أصبتُ أو أخطأتُ، تناولتُ الموضوع بخفّة مزرية أو عمقٍ أكثر من اللازم، لكن ما أنا على يقين منه أنني في كلٍ كنتُ حقيقيًا جدًا صادقًا وأمينًا ولو كان في ذلك بعضُ الكشف عما يحذر الآخرون عادة من كشفه عن أنفسهم", "/images/products/9789778202854.webp", "9789778202854", "عطايا الاربعين", 266, 190m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 295, "إبراهيم عبد المجيد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أذكر عام ١٩٧٩ وكنت عائدا من العمل لمدة عام في المملكة العربية السعودية، أن وجدت بين شرائط التسجيل رباعيات صلاح جاهين بصوت على الحجار والحان سيد مكاوي، فجعلتها لملا فراغ البيت كل يوم، لا أوقفها إلا قبل أن أنام كانت هذه أول مرة استمع تعلى الحجار فاحبيته جدا، أما سيد مكاوي فعشق قديم لا ينتهي صلاح جاهين كثير من معاني و وتأملات صلاح جاهين تدخل بك في المنطقة الوجودية لفهم العالم أو الإحساس به، وتذكرتي برباعيات الخيام، فهي أيضا تدخل بك في منطقة المعالي الوجودية للعالم والبشر والحياة ورغم أني قاري للفلسفة، وأعرف هذه المعاني ومة باني ومقتنع بها فكريا وروحيا الا أن صياغتها الشعرية تغنيك عن عشرات الكتب الفلسفية، وحين تسمعها غناء تتسع الدنيا حولك رغم أن كثيرا منها يوحي بالعدم كنهاية لكل شده او كفراغ يحيط بنا وإن لم نكن نراه.", "/images/products/9789778202489.webp", "9789778202489", "روايات لم ترو", 388, 260m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 296, "شريف سعيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتوالي الأحداث الاقتصادية المتوترة في الفترات الحالية مما يشكل ضغط كبير علي متخذ القرار فرد او مؤسسة في ظل تلك الأحداث اصبح فرض علي الجميع تعلم اللغة الاقتصادية والمفاهيم المالية الأساسية لتحقيق توازن في الجانب المالي من الحياة وتعلم سبل النجاة من الازمات الاقتصادية العاصفة , سيدعمك هذا الكتاب في نمو عقليتك الاقتصادية ودعمك في اتخاذ قرارات مالية سليمة بناء علي رؤية واضحة ومفاهيم تم قياسها من قبل , هذا الكتاب هو مفهوم اقتصادي أساسي ما لا يسع الانسان جهلة الآن , فتم اعداد الكتاب ليناسب كل الناس من المتخصصين وغير المتخصصين بلغة سهلة وأنيقة ومفاهيم حياتية يمكن تطبقها في الحياة العملية ...", "/images/products/9789778202601.webp", "9789778202601", "فن اللعبة", 128, 140m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 297, "سارة مجدي", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "العلاقات الغير صحية التي تؤثر على الصحة النفسية هي العلاقات التي تسبب ضغوطا نفسية وتأثيرا سلبيا على العافية العقلية والعاطفية للفرد. قد تشمل هذه العلاقات العنف الجسدي أو العاطفي، التنمر الإهمال العاطفي، الاضطهاد، وعدم وجود دعم اجتماعي أو علاقات غير مستدامة تؤثر هذه العلاقات الغير صحية على الشعور بالثقة بالنفس، والسعادة، والاستقرار العاطفي، وقد تزيد من خطر الإصابة بالاضطرابات النفسية مثل الاكتئاب والقلق من المهم التعامل مع هذه العلاقات بشكل صحيح والبحث عن الدعم اللازم للحفاظ على صحة نفسية جيدة.\n\nيتناول الكتاب قصصا حقيقية عن العلاقات السامة\" ويسلط الضوء على العلامات التي تشير إلى وجودك في علاقة غير صحية، بالإضافة إلى كيفية الخروج منها بأقل قدر ممكن من الخسائر..", "/images/products/9789778202595.webp", "9789778202595", "علاقة منتهية الصلاحية", 116, 140m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 298, "طاهر المعتز بالله", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الكتاب يكشف القصة المثيرة وغير المعلنة لرحلة صعود رجل غامض من شوارع لينينغراد القاسية إلى القمة. استعد للغوص في عالم مليء بالمؤامرات السياسية، الصفقات السرية، والمعارك الخفية داخل أروقة الكرملين. يعرض الكتاب قصة بوتين من بداية عمله كضابط مخابرات في جهاز الـ KGB إلى أن أصبح سيد الكرملين بلا منازع، المتحكم في مصير أمة بأكملها. إنها حكاية الصعود إلى السلطة، حيث يلتقي المكر بالذكاء، ويختلط الطموح بالخيانة، لتظهر الصورة الحقيقية لرجل لا يعرف حدودًا لتحقيق أهدافه. رجل قد يكون في نظر البعض أقوي رجل في العالم. الكتاب أيضا يجيب علي أسئلة أخري مثل كيف بدأت الحرب الروسية الأوكرانية؟ ولماذا أسست الولايات المتحدة مع دول أوروبا الغربية حلف الناتو؟ وكيف أصبح ممثل كوميدي مثل زيلينسكي رئيسا لأوكرانيا؟ لماذا تدخلت روسيا في الانتخابات الأمريكية؟ وهل تم اغتيال ياسر عرفات؟ كل ذلك وأكثر تجدوه داخل كتاب القيصر.", "/images/products/9789778202533.webp", "9789778202533", "القيصر", 590, 375m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 299, "خلف جابر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا لو ظهر لك أحدهم ليخبرك أنه أنت ولكن من عَالمٍ موازٍ؟ هل تقبل لو عرض عليك تبادل الأدوار والعوالم؟ هل ستجرؤ على إخبار أحدٍ بذلك؟ هل سيصدقك الناس أم سيشُكّون في قواك العقلية؟ والأهم من ذلك، كيف يمكن أن تقرر شخصية روائية مصير كاتبها؟!\n\nفي أحد الأيام، بينما يعاني الدكتور أحمد خالد توفيق من قفلة الكاتب، يتلقى مكالمة هاتفية بعد منتصف الليل من مجهول، ويطلب منه مقابلته في اليوم التالي ليعرض عليه أمرًا ما، وحين يسأل المُتصل عن اسمه، يقول له: «أنا أحمد خالد توفيق»!\n\nإنها كأسطورة رفعت إسماعيل عندما ظهر له قرينه ونغص عليه حياته، فحاول التخلص منه وتدميره. لكن الأمر هذه المرة مُختلف؛ فقد اقترح قرين العراب أن يتبادلا الأدوار لأن كل منهما يعيش حياة مملة، والأغرب أنه أراد الاحتكام في ذلك الأمر إلى دكتور «رفعت إسماعيل» الشخصية الروائية الشهيرة في سلسلة ما وراء الطبيعة! كيف سيتصرف دكتور «أحمد»؟ هل سيوافق على عرضه أو أم سيحتكم إلى رفعت إسماعيل صاحب التصرفات الحمقاء في بعض الأحيان؟ وفي تلك الحالة، من منهما سيختاره رفعت ليعيش في العالم الأرضي؟!\n\nرحلة غرائبية ممزوجة بذكرياتٍ دافئة وتفاصيل مختلفة من حياة دكتور أحمد خالد توفيق. نتتبع فيها طفولته وشبابه وبداياته في الكتابة، وبداية دخوله للمؤسسة العربية الحديثة التي تعد محطة انطلاقه الحقيقي في عالم الأدب ليصبح عراب أدب الرعب. كما نتعرَّف على علاقته الشائكة والملتبسة بـ«رفعت إسماعيل»، وعلاقته بالسينما وأمنيته أن يرى أحد أعماله على شاشة السينما، وكيف أنه تنبأ بحدوث ذلك بعد موته! وكيف كان موته حدثًا مُزلزلًا في حياة كثيرين!", "/images/products/9789778202298.webp", "9789778202298", "أسطورة أحمد خالد توفيق", 152, 130m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 300, "أمير تاج السر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الكتاب عبارة عن مقالات متنوعة للكاتب درج على نشرها في بعض الصحف والمواقع وفيها يتعرض لظاهرة الإبداع من نواح شتى، يكتب عن الإبداع نفسه والمبدعين، ويستعرض كتبا قرأها وأفادته في تجربته الخاصة، وكتب لم تمده بشيء، يتعرض لظواهر الكتابة وللكتب التي تنتشر بسرعة ومبررات انتشارها من وجهة نظره.\nالكتاب اشتمل على حوالي 40 مقالا منها مقالات عن ساحر الكتابة بورخيس بحسب شهادة الكاتب الأرجنتيني ألبرتو مانغويل الذي كان يوما يقرأ لبورخيس بعد إصابته بالعمى، بورخيس الكبير لكن المتواضع الذي يستفيد حتى من آراء المبتدئين في كتابته، بعكس كثير من كتابنا العرب الذين يصيبون قليلا من الشهرة، ويتعالون على القراء..تعرض تاج السر في كتابه، للقارئ باعتباره الهدف الأساسي الذي تسعى الكتابة لاسترضائه، وكيف أن بعض القراء قد لا يفهمون جيدا ويعممون عدم فهم للآخرين، ومواقع القراءة التي أضحت مشنقة للكتب التي ربما يكتب عنها من لم يقرأها أصلا، وسمع عنها فقط وسماها الكاتب بحماقات الإنترنت ؛ حيث يتخيل كثير من الناس أن الكتابة نقل مباشر للواقع ولا يعرفون وظيفة الخيال المهمة، في عملية صناعة النص، وقد تعرض الكاتب لشخصيات، ليست واقعية أصلا واشتهرت في بعض النصوص وتم إلباسها لشخصيات موجودة في الواقع في أمكنة ما، وبالتالي، فصلت لها هوية واقعية بلا وجه حق، ومنها شخصية \" سيف الدين \" في رواية \" عرس الزين \" للطيب صالح، وكانت شخصية خيالية، تم رسمها في الواقع في القرية التي يعيش فيها. تعرض الكتاب أيضاً في مقالات لرموز الكتابة الراحلين، ومنهم جمال الغيطاني الذي رحل مؤخرا، وكيف أن تسمية شارع باسمه في منطقة الجمالية، يعد تكريما كبيرا له، ويتمنى لو عممت مثل هذه التكريمات على كل المبدعين.أيضا تعرض الكاتب لمواضيع وقضايا الكتابة الأثيرة لدى معظم كتاب العالم الثالث، مثل قضية التهميش والفقر، وذكر أن أليس مونرو الكندية، بالرغم من حياتها في بلد متحضر، إلا أنها دأبت على الكتابة في مواضيع التهميش، والفقراء . وعن قضية اللاجئين، والهجرات غير المشروعة، وتحطم الأحلام بالغرق، كقضية الطفل السوري إيلان، وكذلك عن كثير من القضايا الإنسانية، وارتباطها بالثقافة والإبداع عموما، تعرض لها الكاتب في: تحت ظل الكتابة.\nلأربعين مقالا", "/images/products/9789778202410.webp", "9789778202410", "تحت ظل الكتابة", 250, 180m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 301, "هدى أنور", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الكتابة وسنينها كتاب يتعرض لرحلة الكتابة بهدف مساعدة كل من يريد وضع قدمه علي طريق الكتابة الإباعية والبدء في الكتابة..\nيحتوي الكتاب علي مجموعة من الفصول يبدأ أولها بالمراحل التمهيدية للكتابة والتجهيز للكتابة وكيف يعرف الكاتب أنه موهوب في الكتابة ثم يتطرق في الفصول اللاحقة إلي كيفية تشكيل عقلية الكاتب ثم إلي تقنيات الكتابة المختلفة ككتابة الرواية وكتابة القصة القصيرة وكتابة الكتاب غير القصصي..\nيتطرق الكتاب بعد ذلك في فصوله الأخيرة إلي تعريف القاريء بعالم النشر وبعض النصائح الخاصة بالنشر وتسويق الكتاب...", "/images/products/9789778202465.webp", "9789778202465", "الكتابة وسنينها", 182, 140m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 302, "محمد عصمت", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"يتتبَّع الكِتاب بشكلٍ أساسيٍّ عدة محاوِر رئيسيَّة في أدب وسينما الرُعب، منذ أن كانَت محض أفكار صغيرة، وحتى وصلت لأن تُصبِح أهم الأفكار التي يلجأ لها كُتَّاب الرُعب ليبنوا عليها رواياتهم وأفلامهم، نبحث في القصص التاريخيَّة عن أول ذكر لهذه الأفكار، ونُتابِع كيف تطوَّرت تلك الأفكار على مر الزمان، كيف نضجَت وكيف تغيَّرَت، وما هي أصولها الحقيقيَّة، وهل من المُمكِن أن نكتشِف أن بعضها ليس مُجرَّد أساطير فقط؟ وإنما حقائِق مُثبَتة؟ أو أمراض موجودة؟\nنبدأ الكتاب بمُناقشة فكرة أو أسطورة الرجل الذئب، أو المذؤوب\nنُبحِر خلال هذا الفصل بين صفحات ملحمة جلجامِش لنرى أول ذِكر للمذؤوبين في التاريخ\nثُم سننتقِل إلى الفصل الثاني الذي يبحَث عن أصل أسطورة الموتى الأحياء أو الزومبي.\nنذهب للفصل الثالِث، الذي يُناقِش الخوف البشري من الدفن حيًا، وكيف تطوَّرت هذه الفكرة عبر الزمن، وكيف طوَّر البشر من آلياتهم وأنفُسهم ليواجِهوا هذا الخوف، والأهم من ذلك.. هل نجحوا في ذلك؟\nثُم سنذهب للفصل الرابِع، الذي يُناقِش الخوف من المرايات، ومن مِنا لا يخشى المرايات، ولا يشُك أنها بوابات لعوالِم أخرى، عوالِم مُرعِبة حقًا..\nبعد ذلك سننتقِل للفصل الخامِس، لنُناقِش وجود الفضائيين، هل هم حقيقيين؟ هل هم محض خيال؟ لكن لو كانوا مُجرَّد خيال.. فلماذا توجَد عشرات الأدِلة الماديَة المُثبَتة علميًا وتاريخيًا التي تُثبِت وجودهم بيننا؟\nوأخيرًا.. ننتقِل للفصل الأخير، حيث سنتحدَّث عن الأرواح والأشباح والمس في الغرب!\n\n\"", "/images/products/9789778201871.webp", "9789778201871", "كيف بدأ الرعب", 222, 160m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 303, "شريف سعيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"إن أكبر نظام اقتصادي هو الحياة ذاتها، فالحياة نظام كريديت (ائتماني) تعطيك الكثير من الموارد وتهيئ لك الظروف الأولى للحياة، فأنت حصلت على جسدك، أهلك، موطنك، عمرك عقلك ... إلخ دون أن تدفع شيئًا، ولكن هل يعني ذلك أن تلك الأشياء مجانية؟\n\nعلى العكس تماما فهي موارد مدفوعة مقدمًا، وتلك الموارد سوف تستخدم وتهلك يوما ما فهي غير متجددة؛ لذلك عليك أن تمتلك الوعي الكامل لتسخير تلك الموارد لتحقيق أكبر مكسب.\n\nهذا الكتاب يصنع جسرًا بين العلم والتطبيق، يحاول تقليل الفجوة بين المعرفة وامتلاك أدوات العمل، لسنوات كنت أحاول فهم لماذا يستطيع بعض البشر تحقيق أكبر مكسب\n\nوالوصول إلى الرفاهية، ويعاني الكثير غيرهم، كنت أحاول\n\nتطوير عقلية تسمح للجميع بامتلاك أدوات اقتصادية فعالة\n\nلتلبية رغباتهم ورفاهيتهم، إنه نظام كاش.\n\nإن امتلاك عقلية الكاش هو استثمار جيد في ذاتك، كذلك امتلاك هذا الكتاب، يعتبر خطوة ناجحة منك في فهم ما يدور حولك، وتطوير عقليتك الاقتصادية لتحقيق حياة أفضل وهذا ما تستحقه.\"", "/images/products/9789778202458.webp", "9789778202458", "كاش", 142, 140m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 304, "أشرف توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ومن هنا بدأت الكارثة.. عرض الناس حيواتهم على (السوشيال ميديا) كعرض الملابس الداخلية على منشر الغسيل، وفرحوا بلعبة (الرأي والرأي الآخر) فقالوا (الرأي) ولعنوا أعضاء (الرأي الآخر). تعاظمت ذواتهم، وصار كل منهم عالما مفتيا أديبا سياسيا اقتصاديا مدربا لكرة القدم، والملايين غيره من الأنعام بل هم أضل سبيلا. والسؤال هنا: لماذا يقبل الناس مثل هذه التدخلات من الآخرين في حياتهم الشخصية؟ ولماذا لا تكون إجابتهم دائما على مثل هذه التدخلات هي الإجابة العظيمة السحرية.. \"انت مالك؟\"؟", "/images/products/9789778201406.webp", "9789778201406", "انت مالك", 140, 120m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 305, "أحمد الخميسي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يضم الكتاب تسعة عشر مقالًا ما بين الترجمة والكتابة،كما يضم الكتاب عدة مقالات عن العلاقات المصرية الروسية،يتطرق أيضًا إلى المصير القاسي للأدباء الروس في عهد ستالين، بدءا من منع كتبهم، ومصادرتها، إلى ملاحقة وسجن وتشريد أولائك الكتاب. وأخيرًا يشتمل الكتاب على مهم عن وضع الأدب الروسي الحديث بعد انهيار الدولة السوفيتية.", "/images/products/9789778200416.webp", "9789778200416", "أوراق روسية", 204, 140m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 306, "أحمد الخميسي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عتبر كتاب \"نساء الكرملين\" الذي أثار اهتماماً واسعاً، دراسة صحفية وفنية ونفسية ـ إن لم يكن أيضا دراسة تاريخية ـ للمصير الصعب، والمأساوي أحيانا، والمجهول للنساء اللواتي قُدر لهنّ أن يصبحن زوجات ل\"زعماء\" الكرملين، وأن يقاسمن أولئك القادة السكن والطعام وتفاصيل الحياة اليومية.", "/images/products/9789776376991.webp", "9789776376991", "نساء الكرملين", 162, 120m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 307, "شريف ثابت", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وهكذا بدأت عملية تحويل السنيما الشتوي الكلاسيكية الضخمة إلى مُجمَع مُكوَن من ٤ شاشات، وكنت أمر على موقع السنيما في طريق عودتي من الكلية لأتفرج على أعمال البناء والتركيب، حتى جاءت اللحظة المُنتظرة وتم افتتاح السنيما في يناير ٢٠٠٠ بحضور نجيب ساويرس وعددٍ من نجوم ونجمات السنيما المصرية\".\nلو انتي/ انتي من مواليد السبعينات والتمانينات فهتعيشوا هنا حالة من النوستالچيا وتسترجعوا معاها أجمل ذكرياتكم من جديد، أيام القمصان المشجرة والكاروهات وشرايط الكاسيت ونوادي الڨيديو وأفلام عادل إمام ونجمة الجماهير وثورة المضحكين الجدد، وتايتانيك والمهمة المستحيلة وغيرهم..\nأما لو انت/ انتي من جيل التسعينات والألفينات، فهتبقى فرصة تركبوا آلة الزمن، وتعيشوا تاريخ حقيقي حصل فعلاً، وتعرفوا تفاصيل مهمة وممتعة عن قصص إنتاج وعرض الأفلام المصرية والأمريكية اللي شوفتوها بعدين على التليفزيونات واللابات.\nيالا بينا؟", "/images/products/9789778200706.webp", "9789778200706", "رينسانس أسيوط", 240, 170m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 308, "شريف ثابت", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مسافة واسعة قطعتها فى الزمان والمكان، وداخل الدماغ أيضاً، منذ تلك الليلة من ربيع عام ٢٠٠٤ والتى جلست فيها داخل إحدى قاعات رنيسانس أسيوط، أتابع مأخوذاً الدراما الملحمية \"الساموراى الأخير\".. كان منطقياً، والعود أخضر آنذاك، أن أخرج من قاعة العرض متأثراً ببطولات الساموراى.. ليس فقط بسبب القدرة الاستثنائية لإدوارد زويك، المخرج الأمريكى العظيم، على حشد أدواته لإخراج دراما شاعرية تخاطب عاطفة المُشاهِد مباشرةً.. ولكن أيضاً لأن رسالة الفيلم ملأى بالكثير من الدغدغة للمشاعر القومية وبخاصة مع تشابه المأزق الحضارى ومفترق الطرق الذى تمر به \"الأمة\" (كانت أدبيات الإسلام السياسى حاضرة بقوة مع صعوده كمشروع مناهض للهيمنة الغربية مقابل الانبطاح العام للأنظمة السياسية العربية) مع ما مرت به \"الأمة اليابانية\"!\nفى النصف الثانى من القرن التاسع عشر..\n\"الامبراطور شغوف بكل ما هو غربي والساموراي قلقون بشأن ذلك، يعتقدون أن الأمور تجري بسرعة شديدة.. وكأن القديم والحديث يتصارعان لتحديد هوية اليايان\"..\nوبدا محاربو الساموراى بما اتسموا به من قوة وشجاعة ونبل وأصالة وإصرار على خوض معركتهم حتى آخر قطرة دم دفاعاً عن \"هويتهم\".. بدوا أقرب ما يكونون لحركات المقاومة ذات الأيديولوچية الإسلامية والتى تقاتل الأمريكان فى أفغانستان والعراق، ومن قبلهم أشاوس حماس فى فلسطين، إلخ..\nالآن، بعد كل هذه السنوات، وبعد الحدث الكبير فى الألفين وحداشر وما تبعه من تداعيات لم ولن تنته.. يمكننا إعادة مشاهدة الفيلم فى ضوء المسافة الكبيرة التى قُطِعَت داخل الزمان والمكان والدماغ، فماذا سنرى؟..", "/images/products/9789776376984.webp", "9789776376984", "أفلام فترة النقاهة", 195, 140m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 309, "محمد عبدالمحسن", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"ما أكثر كتب التاريخ المنسية على أرفف مكتباتنا، التي تم هجرانها خوفًا من الموت ضجرًا، نتيجة لأسلوب السرد الأكاديمي الذي لا يطيبُ إلا لمن يهواه فقط، فبغض النظر عن كم الإثارة والمتعة في تقصي أخبار الماضي وتفنيد أحداثه سواء تلك التي تخص أفراد بعينهم أو مجتمعات كاملة، إلا أن طريقة عرض المعلومات نفسها تقتل أي شغف تجاه محاولة استطلاع تلك الكتب، فتُترك على حالها كما هي حتى تذبُل.\nوهذا ما ابتعدت عنه تمامًا عند سردي لأحداث هذا الكتاب ...\nفتعمدّت أن تكون الأحداث التاريخية المذكورة بين دفتيّ هذا الكتاب في نسيج مختلف عن المُعتاد، حيث تدور الأحداث في إطار أدبي أشبه بالرواية، فيبدأ الحديث بـ (يوسف) المهندس الذي ترك مجال الهندسة من أجل شغفه فيما يُسمى بمهنة الـ Fixer Upper، وهو مَن يقوم بشراء المنازل والشقق القديمة ويقوم بتجديدهم وإضافة لمسات عصرية سواء في البنية التحتية للعقار أو الأثاث وخلافه، وهذا ما يستمتع (يوسف) بالقيام به بمساعدة فريقه الخاص، حتى تأتي إليه فرصة تفقد فيلا قديمة معروضة للبيع عبر سمسار عقارات في منطقة الزمالك.\nوهنا يتمكن من العثور على غرفة أرشيف منسية تحت أرضية غرفة المكتب تضم لوحات وتحف فنية قديمة ومقتنيات كانت لصاحب الفيلا سابقًا، ومن ضمن محتويات الغرفة سيجد جرامافون قديم مع صندوق به عدة أسطوانات ومعنون بـ (سري للغاية)، وهنا سيدب الفضول في نفس (يوسف) وسيجرب إحدى الأسطوانات ليجد شخصًا ما يحكي أن لديه وسيلةٍ ما غامضة مكّنته من حضور أحداث تاريخية بنفسه كشاهد عيان لما حدث وقتها وهذا هو ما يسرده الرجل في حكاياته التي سجلها على الأسطوانات إياها.", "/images/products/9789778202366.webp", "9789778202366", "حكايات صاحب الصندوق", 214, 150m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 310, "أدهم هلالي", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إختصار لسنين من التجارب والحوارات والنقاشات والخبرات ..اعرف نفسك بشكل أعمق ..إعرف شريك حياتك بكل تفاصيله ...إتناقش مع نفسم او مع شريك حياتك .. في التفاصيل دى.. قرب من نفسك ومن شريك حياتك بشكل سريع", "/images/products/9789778200577.webp", "9789778200577", "لعبة الأسئلة", 252, 110m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 311, "ندى ترك", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الحياة بتعدي علينا زي الهوا، سنين العمر بتفوت بين الحزن والخوف والقلق والمشاكل، بنكرر نفس الأخطاء ونقع في نفس دايرة العلاقات المؤذية..\nبندور علي الناس اللي تتعبنا وتوجعنا.. ونلزق فيهم ونديهم مفاتيحنا يبيعوا ويشتروا فينا ويطفونا ويسرقوا عمرنا\nونقنع نفسنا اننا ماتقدرش نعيش منغيرهم...\nعشان نكسر الدايرة دي ونخرج منها عايزين أفكار جديدة مافكرناش فيها قبل كدة..\nوأفعال جريئة ماعملنهاش قبل كدة..\nعايزين نغير الMindset بتاعتنا عشان نلعبها صح ونفرض احنا قوانينا..\nكتاب “ستMind” لكل ست عايزة تعمل Restart وتبتدي حياتها من أول وجديد..", "/images/products/9789778200829.webp", "9789778200829", "مايند ست", 248, 180m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 312, "كمال شودري", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يتبوَّأ كمال شودري مكانة خاصة في عالم الشعر البنغالي المعاصر بفضل تفرُّدِه في الأسلوب وغزارته في الإنتاج في مواضيع مختلفة، فعلى مدى العقود الأربعة الماضية، نشر الشاعر ستة عشر ديوانًا شعريًّا سبر من خلالها غور الشعر بكافة أشكاله، وجاء هذا الكتاب الذي بين أيدينا ليتضمن مجموعة حصرية من أعمال الشاعر تحتوي على 125 قصيدة مختارة من عشرة من دواوينه، ترجمها إلى العربية المترجم محمد دباجة.\nتمثل هذه القصائد بالنسبة للشاعر اكتشافًا للذات بقدر ما هي استكشاف للفرح والحزن والمخاوف والدوافع؛ كما تمثل استكشافًا للحياة والموت  والإنسان والطبيعة، وهي تأخذ القارئ وتطوف به خلال رحلة عبر بنغلادش، حاضرها وماضيها – منازلها العادية، حقول أرُزها وضفاف أنهارها ومدنها وبلداتها – لتصل به إلى أبعد من ذلك، إلى صحاري مصر وإلى سافانا كينيا أو إلى زاوية ما في أوروبا أو في أميركا الشمالية.", "/images/products/9789778201215.webp", "9789778201215", "قصائد مختارة", 240, 170m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false }
                });
